  "* These figures are provided as general guidance only. Actual consumption will vary based on your team's size, workflows, and usage patterns.": "* 这些数字仅供一般参考。实际消耗会因你团队的规模、工作流和使用模式而异。",
  "**A sales rep if you want one.** For complex or large deals, I'll hand you to a teammate with everything you've shared already in context. I'm an AI and can make mistakes.": "**如果你需要，可安排一名销售代表。**对于复杂或大型交易，我会将你转交给一位团队成员，并附上你已分享的所有背景信息。我是 AI，可能会犯错。",
  "**A sales rep if you want one.** For complex or large deals, I’ll hand you to a teammate with everything you’ve shared already in context.": "**如果需要，可以安排一位销售代表。**对于复杂或大型交易，我会把你交给一位队友，并把你已分享的所有内容放在上下文中。",
  "**Coding & development.** You'll get the most out of Claude Code.": "**编码和开发。** 您将从 Claude Code 中获得最大收益。",
  "**Free to talk.** This conversation doesn't count against your usage.": "**免费交流。**此对话不计入你的用量。",
  "**Free to talk.** This conversation doesn’t count toward your usage.": "**自由对话。** 此对话不计入您的用量。",
  "**I already know your account.** If you're using Claude, I can see your current plan, seats, and usage. We don't train on your data.": "**我已了解您的账户。**如果您正在使用 Claude，我可以看到您当前的套餐、席位和用量。我们不会使用您的数据进行训练。",
  "**I already know your account.** If you’re using Claude, I can see your current plan, seats, and usage.": "**我已经了解您的账户。** 如果您正在使用 Claude，我能看到您当前的套餐、席位数和用量。",
  "**Nothing sensitive needed.** I can find the right plan with some basic information. Please keep confidential details out of chat.": "**不需要任何敏感信息。**我可以用一些基本信息找到合适的套餐。请将保密详情留在聊天之外。",
  "**Ooh, a PM.** Cowork is great for context-gathering and synthesis. Try Claude Code if you want to prototype without help from eng. Where do you want to start?": "**哦，是一位产品经理（PM）。** Cowork 非常适合信息搜集与综合分析。如果您想在没有工程团队协助的情况下快速制作原型，可以试试 Claude Code。您想从哪里开始？",
  "**Ooh, a designer.** Cowork is great for sorting through feedback or writing up research. Try Claude Code if you want to turn designs into something real. Where do you want to start?": "**噢，一位设计师。** Cowork 非常适合整理反馈或撰写研究报告。如果您想将设计转化为真实的东西，请尝试 Claude Code。您想从哪开始？",
  "**Ooh, an engineer.** You'll get the most out of Claude Code. It runs in your terminal, your editor, or wherever you're already working.": "**哦吼，又一位工程师。** 您将从 Claude Code 中获得最大受益。它可以运行在您的终端、编辑器，或任何您已经在工作的地方。",
  "**Ooh, data science.** Claude Code works well with notebooks. Cowork is great for handing off cleanup or exploration. Where do you want to start?": "**哦，是数据科学领域呀。** Claude Code 与 Notebook 配合非常默契。Cowork 则非常适合处理清理或探索性的后续工作。您想从何处开始？",
  "**Ooh, you're in finance.** I can work with you directly in Excel, or you can hand things off in Cowork and come back when they're done. Where do you want to start?": "**真巧，你在金融部门工作。** 我们可以在 Excel 中直接协作，或者你可以把任务交托给 Cowork，完成后再回来。你想从哪里开始？",
  "**Ooh, {role}.** Let's start working together in Cowork. I can work directly in your files, browser, and the tools you already use.": "**奥，{role}。** 让我们开始在 Cowork 中合作。我可以直接处理您的文件、浏览器以及您已在使用的工具。",
  "**The best price you'll get.** I always check the latest pricing.": "**你能拿到的最优价格。**我始终会查询最新定价。",
  "**The best price you’ll get.** I’ll check for our latest pricing.": "**这是您能拿到的最优惠价格。**我来查一下我们的最新定价。",
  "**The fastest path in.** You'll have a quote and a plan by the end of this conversation.": "**最快的入门途径。**在本次对话结束时，你将获得一份报价和一份方案。",
  "**The fastest path in.** You’ll have a quote and a plan by the end of this conversation.": "**最快的入门方式。** 本次对话结束时，您就会得到报价和套餐。",
  "**{roleName}.** You'll get the most out of Claude Code.": "**{roleName}。** 你将最充分地发挥 Claude Code 的价值。",
