  "API requests made with this organization’s keys, and Console sign-ins, from an IP address outside {count, plural, one {the listed range} other {the # listed ranges}} will be rejected immediately. Make sure every network your servers and members connect from, such as data centers, CI, offices, VPNs, and proxies, is covered first.": "使用此组织密钥发起的 API 请求以及 Console 登录，如果来自{count, plural, one {所列范围} other {所列 # 个范围}}之外的 IP 地址，将被立即拒绝。请先确保您的服务器和成员连接所用的每个网络（如数据中心、CI、办公室、VPN 和代理）都被覆盖。",
