  "Ability to share projects with everyone in your organization. When off, projects can still be shared with individual users.": "可将项目分享给组织内的所有人。关闭时，项目仍可分享给单个用户。",
  "Ability to share skills with everyone in your organization at once. Revoking this capability does not revoke previously shared skills.": "可一次性将技能分享给组织内的所有人。吊销此能力不会撤销之前已分享的技能。",
  "Ability to share skills with specific people in your organization. Revoking this capability does not revoke previously shared skills.": "与组织中特定人员分享技能的能力。撤销此能力不会撤销先前已分享的技能。",
