  "Absolute URL identifying the gateway as the access-token audience. Sent as the RFC 8707 resource parameter when set; leave unset for Microsoft Entra ID.": "将网关标识为访问令牌受众的绝对 URL。设置后会作为 RFC 8707 resource 参数发送；对于 Microsoft Entra ID，请保持未设置。",
  "Absolute folder path. May start with ~ or one of the listed %VAR% tokens, expanded per user. Subfolders are included.": "文件夹绝对路径。可以以 ~ 或列出的某个 %VAR% 变量开头，并按用户展开。包含子文件夹。",
  "Absolute path": "绝对路径",
  "Absolute path to an executable that prints a JSON object of HTTP headers on stdout. Merged over static headers; the helper wins on conflict.": "可执行文件的绝对路径，该文件在 stdout 上输出一个由 HTTP 标头组成的 JSON 对象。会与静态标头合并；冲突时以辅助脚本为准。",
  "Absolute path to an executable that prints a JSON object of bootstrap request headers. Merged over the static headers; the helper wins.": "可打印 JSON 对象形式引导请求标头的可执行文件的绝对路径。会与静态标头合并；辅助脚本的值优先。",
  "Absolute path to an executable that prints a JSON object of collector headers. Merged over the static headers and Collector authentication; the helper wins.": "可执行文件的绝对路径，该文件输出一个由收集器标头组成的 JSON 对象。会与静态标头和收集器身份验证合并；冲突时以辅助脚本为准。",
  "Absolute path to an executable that prints the credential, optionally with per-request headers.": "用于打印凭据的可执行文件的绝对路径，可选地附带每请求标头。",
  "Absolute path to service-account JSON. Leave blank to fall back to ADC.": "服务账户 JSON 的绝对路径。留空则回退到 ADC。",
  "Absolute path to the aws executable, shared with the Bedrock profile setting. Not passed to the helper script.": "aws 可执行文件的绝对路径，与 Bedrock 配置文件设置共享。不会传递给辅助脚本。",
  "Absolute path to the aws executable. Leave unset to find it on PATH.": "aws 可执行文件的绝对路径。留空则会在 PATH 中查找。",
