  "Access to fast mode in Claude Code. Fast mode has the same intelligence with significantly faster output. It uses more credits and is billed via usage credits.": "在 Claude Code 中访问快速模式。快速模式具有相同的智能，但输出速度显著更快。它消耗更多额度，并通过用量额度计费。",
