  "Adding your full transcript to the public archive helps researchers, policymakers, journalists, and curious readers around the globe build a clearer picture of how AI impacts people’s lives. It also puts what you want from Anthropic and other AI labs on the record.": "将您的完整对话记录加入公共存档，有助于世界各地的研究人员、政策制定者、记者和好奇的读者更清晰地了解 AI 如何影响人们的生活。这也能把您对 Anthropic 及其他 AI 实验室的期望记录在案。",
