  "Adoption, error rate, and trend per skill across your organization. Error rate is a session-level proxy.": "您组织中每项技能的采用率、错误率和趋势。错误率是一项会话级别的近似指标。",
  "Advanced": "高级",
  "Advanced Calculators and Conversion Tools Powered by Claude AI": "由 Claude AI 驱动的先进计算器和转换工具",
  "Advanced SCIM provisioning is enabled. Seat types and roles are managed through your identity provider.": "高级 SCIM 配置已启用。席位类型和角色将通过您的身份提供商进行管理。",
  "Advanced file analysis": "高级文件分析",
  "Advanced options": "高级选项",
  "Advanced settings": "高级设置",
  "Advanced: CEL condition": "高级：CEL 条件",
  "Advertising": "广告",
  "Advisor": "顾问",
  "Aerospace engineer": "航空航天工程师",
  "Affected accounts will be deleted after {days} days, whether users migrate or not": "无论用户是否迁移，受影响的账户将在 {days} 天后被删除",
  "After clicking, you can close this tab and return to Canvas.": "点击后，您可以关闭此标签页并返回 Canvas。",
  "After deleting this role, <b>{count, plural, one {# user} other {# users}}</b> will have no custom roles assigned. They will no longer have access to any features enabled by custom roles.": "删除此角色后，<b>{count, plural, one {# 位用户} other {# 位用户}}</b>将没有分配自定义角色。他们将无法再访问自定义角色启用的任何功能。",
  "After editing code, Claude will automatically start the preview server, verify changes, and share proof before completing its response. This setting is saved in .claude/launch.json for this project.": "编辑代码后，Claude 将自动启动预览服务器、验证更改并在完成响应前分享证明。此设置保存在此项目的 .claude/launch.json 中。",
  "After enabling HIPAA compliance, your organization settings will be updated to support only the Eligible Services defined in the BAA and Implementation Guide. Products and features that are not Eligible Services under Anthropic's BAA (including MCPs, Claude in Chrome, and beta features) will be disabled for all members of your organization.": "启用 HIPAA 合规后，您的组织设置将更新为仅支持 BAA 和实施指南中定义的合格服务。根据 Anthropic 的 BAA，不属于合格服务的产品和功能（包括 MCP、Claude in Chrome 和测试版功能）将对您组织的所有成员禁用。",
  "After enabling HIPAA compliance, your organization settings will be updated to support only the Eligible Services defined in the BAA and Implementation Guide. Products and features that are not Eligible Services under Anthropic’s BAA (including MCPs, Claude in Chrome, and beta features) will be disabled for all members of your organization.": "启用 HIPAA 合规后，您的组织设置将更新为仅支持 BAA 和实施指南中定义的合格服务。不属于 Anthropic BAA 中合格服务的产品和功能（包括 MCP、Claude in Chrome 和测试版功能）将对您组织的所有成员禁用。",
  "After enabling, your workspace will be limited to the Eligible Services defined in the BAA and Implementation Guide. Products and features that are not Eligible Services (including MCPs, Claude in Chrome, Cowork, and beta features) will be disabled by default for all members of your organization.": "启用后，你的工作区将仅限于 BAA 和实施指南中定义的合格服务。不属于合格服务的产品和功能（包括 MCP、Claude in Chrome、Cowork 和 Beta 功能）将默认对组织中的所有成员禁用。",
  "After every push": "每次推送后",
  "After my meetings, post a summary to my team channel — decisions, action items with owners, open questions — and remind owners 2 days before the next meeting if their item is still open. Pull the data from my connected tools. If you're missing a source, ask before building.": "在我的会议结束后，向我的团队频道发布一份摘要 — 包括决策、带负责人的行动项、待解决的问题 — 并在下次会议前 2 天提醒负责人，如果他们的事项仍未解决。从我连接的工具中获取数据。如果缺少数据源，请在构建前询问。",
  "After saving, you'll get a token and a curl snippet on the routine detail page. Send a POST request whenever you want it to run.": "保存后，您将在例程详情页面上获得一个令牌和一个 curl 代码片段。随时发送 POST 请求以运行它。",
  "After these changes, <b>{count, plural, one {# user} other {# users}}</b> will have no custom roles assigned. They will no longer have access to any features enabled by custom roles.": "这些更改后，<b>{count, plural, one {# 位用户} other {# 位用户}}</b>将没有分配自定义角色。他们无法再访问自定义角色启用的任何功能。",
  "After upload, your skill goes through a brief <a0>security scan</a0> (usually 1–2 minutes) before it’s ready to use. <a1>Learn more about skills</a1> or <a2>see an example</a2>.": "上传后，您的技能会经过简短的<a0>安全扫描</a0>（通常 1–2 分钟），然后才能使用。<a1>详细了解技能</a1>或<a2>查看示例</a2>。",
  "After you connect, admins of {organizationName} can give Claude access to repositories on your GitHub account.": "连接后，{organizationName} 的管理员可以授权 Claude 访问您 GitHub 账户上的仓库。",
  "After you submit, our team will review your server's connection details, listing content, and data-handling practices. You'll receive an email at your primary contact address when the review is complete or if we need anything else from you. Approved servers are published to the directory and become connectable immediately.": "提交后，我们的团队将审核你服务器的连接详情、上架内容和数据处理实践。审核完成后，或如果我们还需要你提供其他信息，我们会向你的主要联系邮箱发送邮件。获批的服务器会发布到目录中，并可立即连接。",
  "After your admin completes these steps, you and your team members will be able to connect individual Microsoft 365 accounts.": "在您的管理员完成这些步骤后，您和您的团队成员将能够连接个人的 Microsoft 365 账户。",
  "After your data downloads, your personal account will close.": "您的数据下载完成后，您的个人账户将被关闭。",
  "After your data downloads, your personal account will close. We can’t cancel or refund your {planName} plan because it’s billed through the App Store. Cancel it in the App Store so you aren’t charged again.": "您的数据下载完成后，您的个人账户将被关闭。我们无法取消或退款您的 {planName} 计划，因为它通过 App Store 计费。请在 App Store 中取消，以免再次被扣款。",
  "After your data downloads, your personal account will close. You’ll get a prorated refund for the rest of your {planName} plan.": "您的数据下载完成后，您的个人账户将被关闭。您将获得 {planName} 套餐剩余时间按比例计算的退款。",
  "After {age} idle, the cache for these {tokens} tokens has expired. Compact now so later replies use a short summary, not the whole conversation.": "闲置 {age} 后，这些 {tokens} 个 token 的缓存已过期。立即压缩，以便后续回复使用简短摘要，而不是整个对话。",
