  "Allowing all unlisted {cliName} commands isn't permitted by your organization's settings. Commands named in this plugin can still be allowed individually.": "你的组织设置不允许允许所有未列出的 {cliName} 命令。此插件中指定的命令仍可单独允许。",
  "Allowing all unlisted {cliName} commands isn’t permitted by your organization’s settings. Commands named in this plugin can still be allowed individually.": "您的组织设置不允许放行所有未列出的 {cliName} 命令。此插件中指定的命令仍可单独放行。",
  "Allowing for this chat also lets other Claude products, like Claude Code, access your Claude Design projects on this account. Change this anytime in <a>design settings</a>.": "为此聊天启用此功能后，也会允许其他 Claude 产品（如 Claude Code）访问此账户上的 Claude Design 项目。可在 <a>设计设置</a> 中随时更改。",
  "Allowing this action comes with risks. Malicious instructions in files, emails, and web content could trick Claude into unintended actions. <a>Learn more</a>": "允许此操作会带来风险。文件、电子邮件和网页内容中的恶意指令可能诱使 Claude 执行非预期操作。<a>了解更多</a>",
  "Allowing this {cliName} command by default isn't permitted by your organization's settings.": "您组织的设置不允许默认允许此 {cliName} 命令。",
