  "Already failed on {failures, plural, one {# runner} other {# runners}}. Auto-recovery was exhausted — retry instead if you want to keep trying.": "已在 {failures, plural, one {# 个运行器} other {# 个运行器}}上失败。自动恢复已耗尽 — 如果您想继续尝试，请重试。",
  "Already failed on {failures, plural, one {# runner} other {# runners}}. The spawn-runner hook then failed too, so nothing is retrying.": "已经在 {failures, plural, one {# 个 runner} other {# 个 runner}} 上失败。随后 spawn-runner 钩子也失败了，因此没有任何内容在重试。",
