  "Always allow saves this transition on this device. Revoke in Settings.": "“始终允许”会把此切换保存到此设备上。可在“设置”中撤销。",
  "Always allow tool approvals by default": "默认总是批准工具请求",
  "Always allow {count, plural, one {# selected connector} other {# selected connectors}}": "始终允许 {count, plural, one {# 个选中的连接器} other {# 个选中的连接器}}",
  "Always allowed": "始终允许",
  "Always allowing these actions carries risks. Content from files, emails, and the web can contain malicious instructions. Reviewing each action helps you catch Claude errors and malicious actions. <a>Learn about safety risks</a>.": "始终允许这些操作存在风险。文件、电子邮件和网络中的内容可能包含恶意指令。审查每个操作可帮助您捕获 Claude 错误和恶意操作。<a>了解安全风险</a>。",
  "Always answer in British English. Never include customer account numbers in a response.": "始终用英式英语回答。绝不在回复中包含客户账号。",
  "Always applies alongside the pools above. Pooled usage counts against this limit too.": "始终与上方的资金池同时适用。池化用量也计入此限额。",
  "Always approve": "始终批准",
  "Always ask before making changes": "做出更改前始终征求许可",
  "Always confirm before Claude handles financial, personal, or work-critical tasks.": "每当 Claude 处理财务、个人或工作关键任务前，始终先进行确认。",
  "Always include admins and owners": "始终包含管理员和所有者",
  "Always on": "始终开启",
  "Always open links in default browser": "始终在默认浏览器中打开链接",
  "Always required": "始终必填",
  "Always show latest version": "始终显示最新版本",
  "Always start with the default model": "始终以默认模型开始",
  "Always there when you need it—Claude sits quietly in your workflow. No tab-hopping required. ": "随需而动——Claude 在您的工作流程中静候调遣，无需频繁切换标签页。",
  "Always use the model Anthropic recommends for enterprise use. Currently, it is {modelName}. This will update automatically when new models are released.": "始终使用 Anthropic 推荐的企业级模型。当前为 {modelName}。发布新模型时会自动更新。",
  "Always use the model Anthropic recommends for enterprise use. This will update automatically when new models are released.": "始终使用 Anthropic 推荐的企业级模型。发布新模型时会自动更新。",
  "Always use the models Anthropic recommends for enterprise use: {defaultsByProduct}. These update automatically when new models are released.": "始终使用 Anthropic 推荐用于企业用途的模型：{defaultsByProduct}。这些模型会在新模型发布时自动更新。",
  "Always uses deep reasoning": "始终使用深度推理",
  "Always uses the model Anthropic recommends for enterprise use. Updates automatically as newer models are released.": "始终使用 Anthropic 推荐用于企业用途的模型。随着新模型发布自动更新。",
  "Always-allow individual tools in connector settings.": "在连接器设置中始终允许单个工具。",
