  "Amended commit": "已修订的提交",
  "Amending commit": "正在修订提交",
  "Amount must be between {min} and {max}.": "金额必须在 {min} 和 {max} 之间。",
  "Amount too high for discount": "金额过高，无法使用折扣",
  "Amounts are USD, after discounts and before credits.": "金额以美元计，已扣除折扣、未扣除积分。",
  "Amounts are discounted billed spend in USD, before credits; the Usage page shows list-price spend against your limits.": "金额为扣除折扣后的已计费支出（美元，抵扣额度前）；用量页面显示的是对照您限额的标价支出。",
  "An AI-powered communication tool that transforms emotionally charged, reactive workplace messages into diplomatic, professional alternatives": "一款由 AI 驱动的沟通工具，可将情绪化、被动的职场消息转化为得体、专业的替代方案",
  "An API error occurred": "发生 API 错误",
  "An Enterprise upgrade is already in progress.": "企业版升级已在进行中。",
  "An OTEL console exporter in settings.json is interfering with Claude Code. Remove the OTEL_*_EXPORTER=console setting and try again.": "settings.json 中的 OTEL 控制台导出器正在干扰 Claude Code。请移除 OTEL_*_EXPORTER=console 设置后重试。",
  "An OTEL console exporter in settings.json is interfering with Claude Code. Remove the OTEL_*_EXPORTER=console setting.": "settings.json 中的 OTEL 控制台导出器正在干扰 Claude Code。请移除 OTEL_*_EXPORTER=console 设置。",
  "An active Team subscription is required to upgrade to Enterprise.": "需要有效的 Team 订阅才能升级到 Enterprise 方案。",
  "An admin can raise the limit in Settings → Usage.": "管理员可在“设置 → 使用情况”中提高上限。",
  "An admin needs to enable Claude Code Security for your organization.": "管理员需要为您的组织启用 Claude Code 安全功能。",
  "An admin needs to enable Claude Security for your organization.": "需要管理员为你的组织启用 Claude Security。",
  "An admin turned off the main-branch watcher for this repository.": "管理员已关闭此仓库的主分支监视器。",
  "An admin turned on Claude Science for your organization, but members haven’t started using it yet.\n\nMembers with access can get an email explaining how to download the app and sign in.": "管理员已为您的组织开启 Claude Science，但成员尚未开始使用。\n\n拥有访问权限的成员可以收到一封说明如何下载应用并登录的电子邮件。",
  "An administrator configured Cowork with settings we can't use. You won't be able to start tasks until your IT team fixes it.": "管理员为协作功能配置了我们无法使用的设置。在你的 IT 团队修复之前，你将无法启动任务。",
  "An administrator configured Cowork with settings we can’t use. You won’t be able to start tasks until your IT team fixes it.": "管理员为 Cowork 配置了无法使用的设置。在您的 IT 团队修复之前，您将无法启动任务。",
  "An agentic coding tool that lives in your terminal.": "一个运行在终端中的自主式编程工具。",
  "An attachment is too large. Remove it and try again.": "某个附件过大。请移除后重试。",
  "An attachment is too large. Start a new session to continue.": "某个附件过大。请开始新会话以继续。",
  "An audit log will be written when deletion has completed.": "删除完成后将写入审计日志。",
  "An egress allow rule will be created for {hostCount, plural, one {this host} other {these hosts}} so the credential can be used.": "将为{hostCount, plural, one {此主机} other {这些主机}}创建一条出站允许规则，以便使用该凭据。",
  "An error occurred during the authentication process. Please try again.": "身份验证过程中发生错误。请重试。",
  "An error occurred when we tried to send an invite to {email}": "我们在尝试向 {email} 发送邀请时出错",
  "An error occurred when we tried to send {count, plural, one {# invite} other {# invites}}": "当我们尝试发送 {count, plural, one {# 份邀请} other {# 份邀请}} 时发生错误",
  "An error occurred while accepting your documents. Please reach out to Anthropic support to request another link.": "接受您的文档时出错。请联系 Anthropic 支持请求另一个链接。",
  "An error occurred while deleting your account. Please try again or contact support.": "删除您的账号时出错了。请重试或联系支持人员。",
  "An error occurred while fetching that resource. Please try again.": "获取该资源时出错。请重试。",
  "An error occurred while loading the security center. You can try again.": "加载安全中心时出错。您可以重试。",
  "An error occurred while processing your registration. Please try again or contact support if the problem persists.": "处理您的注册时发生错误。如果问题持续存在，请重试或联系支持团队。",
  "An error occurred while trying to run the generated artifact.": "尝试运行生成的构件时发生错误。",
  "An export of this document is already in progress. Try again when it finishes.": "此文档的导出已在进行中。请在其完成后重试。",
  "An identity provider was removed. These unsaved mappings were bound to it and were removed: {mappings}.": "某个身份提供方已被移除。这些未保存的映射与之绑定并被一并移除：{mappings}。",
  "An image couldn't be read. Rewind to remove it and try a different format.": "无法读取某张图片。请回退以将其移除，并尝试其他格式。",
  "An image couldn’t be read. Rewind to remove it and try a different format.": "无法读取一张图像。请回退以移除它并尝试其他格式。",
  "An image couldn’t be read. Start a new session to continue.": "无法读取一张图像。请新建一个会话以继续。",
  "An image in this conversation is over 2000px. Rewind to remove it, or start a new session.": "此对话中有一张图片超过 2000 像素。请回退以将其移除，或开始一个新会话。",
  "An image in this conversation is over 2000px. Start a new session to continue.": "此对话中的一张图片超过 2000px。请开始新会话以继续。",
  "An import is already running.": "已有导入正在进行。",
  "An import is already running. Wait for it to finish, then try again.": "已有导入正在进行中。请等待其完成后再重试。",
  "An integration is asking: “{title}”": "某个集成在询问：“{title}”",
