  "Are you sure you want to delete \"{connectionName}\"? This action cannot be undone.": "确定要删除 “{connectionName}” 吗？此操作无法撤销。",
  "Are you sure you want to delete \"{name}\"?": "确定要删除 “{name}” 吗？",
  "Are you sure you want to delete \"{name}\"? This action cannot be undone.": "确定要删除\"{name}\"吗？此操作不可撤销。",
  "Are you sure you want to delete \"{name}\"? Your app will no longer have access to this value.": "您确定要删除\"{name}\"吗？您的应用将无法再访问此值。",
  "Are you sure you want to delete the domain <strong>{domain}</strong>?": "确定要删除域名 <strong>{domain}</strong> 吗？",
  "Are you sure you want to delete the group \"{groupName}\"? This action cannot be undone.": "确定要删除群组“{groupName}”吗？此操作无法撤销。",
  "Are you sure you want to delete the group “{groupName}”? Group members lose access to any projects shared with this group. This action cannot be undone.": "确定要删除群组“{groupName}”吗？群组成员将失去对该群组共享的所有项目的访问权限。此操作无法撤销。",
  "Are you sure you want to delete the group “{groupName}”? This action cannot be undone.": "确定要删除群组“{groupName}”吗？此操作无法撤销。",
  "Are you sure you want to delete the managed settings? This can't be undone.": "你确定要删除托管设置吗？此操作无法撤销。",
  "Are you sure you want to delete the managed settings? This cannot be undone.": "确定要删除托管设置吗？此操作不可撤销。",
  "Are you sure you want to delete the managed settings? This can’t be undone.": "确定要删除托管设置吗？此操作无法撤销。",
  "Are you sure you want to delete the role \"{roleName}\"? This action cannot be undone.": "确定要删除角色“{roleName}”吗？此操作无法撤销。",
