  "Artifacts": "构件",
  "Artifacts are created by other users and aren’t verified by Anthropic. Only download files you trust.": "构件由其他用户创建，未经 Anthropic 验证。请仅下载您信任的文件。",
  "Artifacts are interactive pages that open in a side panel. <b>Cancel</b> to have Claude include it in the reply instead.": "工件是在侧边面板中打开的交互式页面。<b>取消</b>则让 Claude 改为将其包含在回复中。",
  "Artifacts are interactive pages that open in the Cowork sidebar on your connected desktop. <b>Cancel</b> to skip creating it.": "制品是在您已连接的桌面上的 Cowork 侧边栏中打开的交互式页面。<b>取消</b>可跳过创建。",
  "Artifacts are user-generated and may contain unverified or potentially unsafe content.": "构件由用户生成，可能包含未经验证或潜在不安全的内容。",
  "Artifacts couldn’t be loaded. Try again.": "无法加载制品。请重试。",
