  "Artifacts guide": "构件指南",
  "Artifacts is required for code execution and file creation, which is enabled by your organization": "代码执行和文件创建需要工件，这已由您的组织启用",
  "Artifacts published in this project appear here.": "在此项目中发布的构件会显示在这里。",
  "Artifacts published in this session appear here.": "在此会话中发布的制品会显示在这里。",
  "Artifacts settings have moved to their own page.": "构件设置已移至独立页面。",
  "Artifacts shared by Claude in this thread will appear here.": "Claude 在此会话中分享的制品会显示在这里。",
  "Artifacts shared with the organization or publicly, most recently updated first. Deleting an artifact permanently removes it and all its versions.": "与组织共享或公开的构件，按最近更新排序。删除构件会将其及其所有版本永久移除。",
  "Artifacts that stay up to date": "保持最新的工件",
  "Artifacts you build with Claude appear here.": "您用 Claude 构建的制品会显示在这里。",
  "Artifacts you’ve published from Claude Code. Deleting one permanently removes its link and versions, but you can publish it again at a new link.": "这些是您从 Claude Code 发布的制品。删除一个会永久移除其链接和版本，但您可以用新链接再次发布。",
  "Artist": "艺术家",
  "Arts and design": "艺术与设计",
  "As of {date} (UTC). Data has a one-day delay.": "截至 {date}（UTC）。数据延迟一天。",
  "As of {date}, members of your organization on Claude desktop for Mac (Xcode required) can have Claude Code build their iOS app, launch the simulator, and verify the result without leaving the session. To keep this off, set the disableMobileSimulatorTools managed setting to true. No action is needed otherwise.": "自 {date} 起，您组织中在 Mac 上使用 Claude 桌面版（需要 Xcode）的成员，可以让 Claude Code 构建他们的 iOS 应用、启动模拟器并在不离开会话的情况下验证结果。要关闭此功能，请将 disableMobileSimulatorTools 托管设置设为 true。否则无需任何操作。",
  "As of {date}, members of your organization with Claude Code Desktop can use Browser, which lets Claude view and interact with web pages in a side-by-side pane. If you’d prefer to keep this off, you can restrict it any time with the managed settings in the linked documentation. No action is needed otherwise.": "自 {date} 起，您组织中拥有 Claude Code Desktop 的成员可以使用 Browser，让 Claude 在并排窗格中查看网页并与之交互。如果您希望保持关闭，可以随时使用链接文档中的托管设置来限制它。否则无需任何操作。",
  "As the primary owner, {fullName} will be able to:": "作为主要所有者，{fullName} 将能够：",
  "As written": "按书面",
  "As you delegate work, you can ask me to directly modify my instructions, add more repositories, send scheduled messages, and more. Start all your work here, and I’ll keep watch over everything running and post updates as things finish or need you.": "在您委派工作时，可以让我直接修改我的指令、添加更多代码仓库、发送定时消息等。在这里启动您所有的工作，我会监视所有运行中的任务，并在完成或需要您时发布更新。",
  "Ask": "询问",
  "Ask Claude": "询问 Claude",
  "Ask Claude a question or start a task…": "向 Claude 提问或开始一个任务…",
  "Ask Claude about your code": "向 Claude 询问你的代码",
  "Ask Claude about {name}": "询问 Claude 关于 {name}",
  "Ask Claude anything": "咨询 Claude 任何问题",
  "Ask Claude to build a live dashboard that stays up to date.": "请 Claude 构建一个能保持实时更新的仪表板。",
  "Ask Claude to build...": "让 Claude 构建……",
  "Ask Claude to commit": "让 Claude 进行提交 (Commit)",
  "Ask Claude to continue, or break the task into smaller steps.": "让 Claude 继续，或将任务拆分为更小的步骤。",
  "Ask Claude to create an artifact from your data, or to update an existing one. Artifacts are local HTML dashboards you can refresh and share.": "让 Claude 根据您的数据创建一个 Artifact，或者更新现有的 Artifact。Artifact 是本地 HTML 仪表板，您可以刷新并分享它们。",
  "Ask Claude to create something": "请 Claude 创建内容",
  "Ask Claude to edit the style...": "请 Claude 编辑样式...",
  "Ask Claude to explain, edit, or fix code right in VS Code.": "在 VS Code 中直接让 Claude 解释、编辑或修复代码。",
  "Ask Claude to find a fix and open a pull request": "让 Claude 寻找修复方案并发起 pull request",
  "Ask Claude to fix": "让 Claude 修复",
  "Ask Claude to generate content like code snippets, text documents, or website designs, and Claude will create an Artifact that appears in a dedicated window alongside your conversation.": "让 Claude 生成代码片段、文本文档或网站设计等内容，Claude 将创建一个构件 (Artifact)，显示在对话旁边的专门窗口中。",
  "Ask Claude to help": "请 Claude 帮忙",
  "Ask Claude to keep an up to date notebook of your open PRs, pending decisions, and open questions for you.": "让 Claude 为您维护一个最新的笔记本，记录您的待处理 PR、待定决策和未决问题。",
  "Ask Claude to make this a Word, Excel, PowerPoint or PDF file you can download without copying and pasting.": "让 Claude 将其生成为 Word、Excel、PowerPoint 或 PDF 文件，您可以直接下载，无需复制粘贴。",
  "Ask Claude to remember something and it'll save it here.": "让 Claude 记住一些事情，它会保存在这里。",
