  "Ask an owner or admin of {orgName} to grant it to you. On Enterprise plans it lives under Organization settings → Roles.": "请联系 {orgName} 的所有者或管理员，为您授予该权限。在 Enterprise 计划中，它位于组织设置 → 角色下。",
  "Ask anything and start working through ideas. No setup required.": "提问任何问题并开始深入思考。无需设置。",
