  "Auth0’s name for the resource indicator. Set this instead of Resource when your token URL is an Auth0 tenant.": "这是 Auth0 对资源指示符的称呼。当您的令牌 URL 是 Auth0 租户时，请设置此项而不是 Resource。",
  "Authenticate in the terminal with /mcp, then click here to reconnect": "在终端中使用 /mcp 完成认证，然后点击此处重新连接",
