  "Auto mode isn’t available for this session. Asking for permissions instead.": "此会话不支持自动模式。改为请求权限。",
  "Auto mode lets Claude handle permission decisions during coding sessions, so developers can run longer tasks without being interrupted by Claude asking for manual approvals. Auto mode also includes additional safeguards against prompt injections.": "自动模式让 Claude 在编码会话期间处理权限决定，这样开发者就可以运行较长时间的任务，而不会被 Claude 请求手动批准所打断。自动模式还包含针对提示词注入的额外防护措施。",
  "Auto mode lets Claude handle permission prompts automatically. Claude checks each tool call for risky actions and prompt injection before executing, runs the ones it assesses as lower-risk, and blocks the rest.": "自动模式让 Claude 自动处理权限提示。Claude 在执行前会检查每次工具调用是否有风险操作和提示注入，运行它评估为较低风险的调用，并阻止其余的调用。",
