  "Automatic installation needs {source, select, url {a Manifest SHA-256} other {a full 40-character commit SHA in Ref}}. Without one this marketplace is treated as available: it is listed, but this setting installs nothing.": "自动安装需要{source, select, url {Manifest SHA-256} other {Ref 中完整的 40 字符提交 SHA}。}缺少时此市场将被视为可用：它会被列出，但此设置不会安装任何内容。",
