  "Automatically approve": "自动批准",
  "Automatically archive desktop sessions when the associated pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept.": "当关联的 Pull request 被合并或关闭时，自动归档桌面会话。归档还会在 Pull request 合并后移除该会话的工作树并删除其分支。未推送的工作会保留。",
  "Automatically archive local sessions after a period of no activity. Sessions that are running or have background work are never archived, and a worktree with uncommitted changes is kept on disk.": "本地会话在一段时间无活动后会自动归档。正在运行或有后台工作的会话永不归档，包含未提交更改的工作树会保留在磁盘上。",
  "Automatically archive sessions when the associated pull request is merged.": "当关联的拉取请求被合并时自动归档会话。",
