  "Avg Vol 50d": "50 日平均成交量",
  "Avoid financial transactions, password management, or anything involving sensitive personal data. Start with trusted sites and familiar workflows where you're comfortable having Claude take actions. Never use it for high-stakes decisions without careful supervision. And, of course, make sure your use complies with our <aupLink>acceptable use policy</aupLink>. <learnMore>Learn more</learnMore>": "避免财务交易、密码管理或任何涉及敏感个人数据的事情。从受信任的站点和您觉得让 Claude 采取操作比较放心的熟悉流程开始。没有仔细监督，绝不要将其用于重大决策。当然，请确保您的使用符合我们的<aupLink>可接受使用政策</aupLink>。<learnMore>了解更多</learnMore>",
  "Avoid financial transactions, password management, or anything involving sensitive personal data. Start with trusted sites and familiar workflows where you’re comfortable having Claude take actions. Never use it for high-stakes decisions without careful supervision. And, of course, make sure your use complies with our <aupLink>acceptable use policy</aupLink>. <learnMore>Learn more</learnMore>": "避免用于金融交易、密码管理或任何涉及敏感个人数据的操作。从可信赖的站点和您熟悉的工作流开始，在这些场景下您比较放心让 Claude 采取行动。在没有仔细监督的情况下，切勿将其用于高风险决策。当然，请确保您的使用符合我们的<aupLink>可接受使用政策</aupLink>。<learnMore>了解更多</learnMore>",
  "Avoid sharing personal information like names or contact details.": "避免分享姓名或联系方式等个人信息。",
  "Avoid sharing personal or other sensitive information that you would not feel comfortable making public. <examples>Examples</examples>": "避免分享您不愿公开的个人或其他敏感信息。<examples>示例</examples>",
