  "Background: Claude works inside the apps you allow while you keep using your computer, and asks your permission before taking full control of your screen. Full control: Claude takes control of your screen, mouse, and keyboard by default whenever Claude uses an app you allow, without asking again.": "后台模式：您继续使用电脑的同时，Claude 在您允许的应用内工作，并在完全控制您的屏幕之前征求您的许可。完全控制模式：每当 Claude 使用您允许的应用时，默认控制您的屏幕、鼠标和键盘，不再另行询问。",
