  "Based on my HubSpot data, tell me the three sales actions that would matter most today — and why those three. Not a report; a short answer I can act on before lunch.": "根据我的 HubSpot 数据，告诉我今天最值得做的三个销售动作——以及为什么是这三个。不要写成报告；给我一个午饭前就能付诸行动的简短答复。",
  "Based on that, pick the single most useful task we could finish in the next few minutes and let's get started — don't give me a menu.": "基于此，选出接下来几分钟内我们最值得完成的一项任务，然后直接开始，不要给我菜单。",
  "Based on the 30-day disconnect rate: of all distinct accounts that sent this server any MCP message in the last 30 days (including incomplete connection attempts), the share that explicitly disconnected this connector. Healthy at 5% or below; degraded above it.": "基于 30 天断开率：在过去 30 天内，向此服务器发送过任何 MCP 消息（包括未完成的连接尝试）的所有不同账户中，明确断开此连接器的占比。5% 及以下为健康；高于该值则表示性能下降。",
  "Based on what my main table tracks, suggest three fields or views that would make it more useful — with what each would show — and create the one I pick.": "根据我的主表跟踪的内容，建议三个能让它更有用的字段或视图——并说明每个会展示什么——然后创建我选中的那个。",
  "Based on what you've described, a smaller plan is the better fit.": "根据你的描述，较小的方案更合适。",
  "Based on {count} conversations analyzed in the last {windowDays} days, as of {date}. <a>Learn more</a>": "基于截至 {date} 过去 {windowDays} 天内分析的 {count} 条对话。<a>了解更多</a>",
  "Based on {count} recent conversations as of {date}. <a>Learn more</a>": "基于截至 {date} 的 {count} 次近期对话。<a>了解更多</a>",
