  "Box": "Box",
  "Brainstorm 4-5 angles for an article, with a punchy one-line hook for each. I'll share the topic next.": "为一篇文章头脑风暴 4 到 5 个角度，并为每个角度配一句有力的钩子文案。我接下来会提供主题。",
  "Brainstorm 4-5 angles for an article, with a punchy one-line hook for each. I’ll share the topic next.": "为一篇文章头脑风暴 4-5 个角度，每个角度附一个有力的一句话钩子。我接下来会分享主题。",
