  "Branch name copied to clipboard!": "分支名称已复制到剪贴板！",
  "Branch name copied to clipboard.": "分支名称已复制到剪贴板。",
  "Branch prefix": "分支前缀",
  "Branch push blocked, and no pushed branch could be found to start a cloud session from. A pre-push hook or a server-side check rejected the push. Commits stay on this device until a machine that can push publishes them.": "分支推送被阻止，且找不到已推送的分支来启动云端会话。pre-push 钩子或服务器端检查拒绝了此次推送。提交将保留在此设备上，直到能够推送的机器将其发布。",
  "Branch push blocked. A pre-push hook or a server-side check rejected it. You can continue without pushing. The cloud session will start from {branch} as the remote last saw it.": "分支推送被阻止。pre-push 钩子或服务端检查拒绝了它。您可以不推送而继续。云端会话将从远端最后看到的 {branch} 开始。",
  "Branch push blocked. A pre-push hook or a server-side check rejected it. You can continue without pushing. The cloud session will start from {branch} as the remote last saw it; {count, plural, one {# commit} other {# commits}} on this device won’t be included.": "分支推送被阻止。pre-push 钩子或服务器端检查拒绝了推送。您可以继续而不推送。云会话将从 {branch} 分支（远程最后一次看到的状态）开始；此设备上的 {count, plural, one {# 个提交} other {# 个提交}}将不会包含在内。",
  "Branch to new chat": "分支到新聊天",
