  "Brief description of your issue": "您问题的简要描述",
  "Brief me before my first meeting": "在我第一次会议前给我简报",
  "Brief me before my first meeting today: what it’s about, who’s in it, and what I should have ready. Then offer to do this automatically every morning before my day starts.": "在今天第一个会议前给我简报：会议主题、参会人、我应该准备什么。然后提议每天早上开始工作前自动为我做这件事。",
  "Brief me before my next meeting": "在我下次会议前给我简报",
  "Brief me for standup": "为我的站会做准备",
  "Brief me for standup right now: my in-progress issues, what changed overnight, and any blockers with my name on them. If it’s useful, set this up to run every weekday morning.": "现在为我准备站会简报：我正在进行的 issue、一夜之间的变化，以及任何带我的名字的阻塞项。如果有用，把这个设置成每个工作日早上运行。",
  "Brief me on my Linear queue right now: new assignments, things that moved overnight, and blockers with my name on them. If it’s useful, run this every weekday morning.": "现在就向我简报我的 Linear 队列：新分配的事项、隔夜变动的项目，以及带我的名字的阻塞项。如果有用，就把它设置成每个工作日早上运行。",
  "Brief me on my biggest deal": "向我简要介绍我最大的那笔交易",
  "Brief only": "仅简述",
  "Briefly describe the bug type": "简要描述错误类型",
  "Bring Claude Code into your favorite IDE.": "将 Claude Code 引入您喜欢的 IDE。",
  "Bring Claude into Chrome, Slack, and more": "将 Claude 引入 Chrome、Slack 等",
  "Bring a draft, even a rough one": "带上草稿，哪怕很粗糙",
  "Bring a project you made in Chat over to Cowork.": "将您在聊天中创建的项目带到 Cowork 中。",
  "Bring a project you made in Chat over to Cowork. Changes in Cowork won't affect your project in Chat.": "将您在聊天中创建的项目带到 Cowork 中。在 Cowork 中的更改不会影响您在聊天中的项目。",
  "Bring a project you made in Chat over to Cowork. Changes in Cowork won’t affect your project in Chat.": "把您在 Chat 中创建的项目带到 Cowork。在 Cowork 中的更改不会影响您在 Chat 中的项目。",
  "Bring any idea to life with chat, Cowork, Claude Code, and Claude Design.": "用聊天、Cowork、Claude Code 和 Claude Design 把任何想法变成现实。",
  "Bring chats and projects from your personal account into {orgName}.": "将您个人账户中的对话和项目导入 {orgName}。",
  "Bring history from another AI": "从另一个 AI 导入历史记录",
  "Bring me anything—a tough problem, a half-formed idea, something you need to write. We’ll figure it out together.": "给我带来任何东西——棘手的问题、半成品创意，或者您需要撰写的内容。我们会一起解决它。",
  "Bring my work to {orgName}": "把我的工作迁移到 {orgName}",
  "Bring over your chats, projects, and sessions": "迁移您的聊天、项目和会话",
  "Bring relevant context and data from another AI provider to Claude. We'll provide a prompt you can use to fetch the memory from your other account.": "将相关背景和数据从另一个 AI 提供商带到 Claude。我们将提供一段提示语，供您从另一个账户中获取该记忆。",
  "Bring two or three thoughts to the retro": "带上两三个想法参加复盘",
  "Bring your chats and projects to {orgName}. Your personal account stays open for about 30 days so you can cancel your App Store subscription.": "将您的聊天和项目迁移到 {orgName}。您的个人账户将保留约 30 天，以便您取消 App Store 订阅。",
  "Bring your chats and projects. You’ll cancel your App Store subscription separately.": "迁移您的对话和项目。您需要单独取消 App Store 订阅。",
  "Bring your chats, projects, and earlier sessions into this app so you can search and continue past work.": "将您的对话、项目和早期会话导入此应用，以便您搜索并继续过去的工作。",
  "Bring your conversations, projects, and files from Claude.ai into Cowork.": "将您的对话、项目和文件从 Claude.ai 引入 Cowork。",
  "Bring your conversations, projects, and files into Cowork so you can search and continue past work.": "将你的对话、项目和文件导入 Cowork，以便你搜索并继续过往的工作。",
  "Bring your data with you": "随身携带您的数据",
  "Bring your file to life in Claude Design": "在 Claude Design 中让您的文件焕发生机",
  "Bring your history over from another AI": "从其他 AI 迁移您的历史记录",
