  "Browse the project beside your file": "在文件旁浏览项目",
  "Browse thousands of AI-powered tools, applications, and interactive experiences built with Claude. Whether you’re looking to streamline your work, learn something new, or explore AI capabilities, discover tools that transform how you create, analyze, and innovate.": "浏览成千上万个基于 Claude 构建的 AI 驱动工具、应用和互动体验。无论您是想简化工作、学习新知识还是探索 AI 能力，都能发现改变您创作、分析和创新方式的工具。",
  "Browse with Claude": "与 Claude 一起浏览",
  "Browse workflow history (running and completed)": "浏览工作流历史（运行中和已完成）",
  "Browse your project's files in a side pane — fuzzy-find by name, search contents with `?`, [[cmd+f]] to find in file": "在侧边窗格中浏览项目文件 — 按名称模糊查找，用 `?` 搜索内容，用 [[cmd+f]] 在文件中查找",
  "Browse your project’s files in a side pane — fuzzy-find by name, search contents with `?`, [[cmd+f]] to find in file": "在侧边栏浏览您项目的文件——按名称模糊查找，用 `?` 搜索内容，[[cmd+f]] 在文件中查找",
