  "Built-in tools removed from Cowork.": "已从 Cowork 中移除内置工具。",
  "Built-in tools, or argument-scoped permission rules such as Read(**/.env), denied in Cowork and Code.": "内置工具，或参数范围的权限规则（如 Read(**/.env)），在 Cowork 和 Code 中被拒绝。",
  "Built-in web search": "内置网页搜索",
