  "Bulk sending isn’t available right now. You can still select and email members individually.": "目前无法批量发送。您仍然可以单独选择成员并发送电子邮件。",
  "Bulk sending isn’t available right now. You can still select and invite members individually.": "批量发送目前不可用。您仍可以单独选择并邀请成员。",
