  "Buy credits": "购买积分",
  "Buy credits anytime or set up auto-reload": "可随时购买额度或设置自动充值",
  "Buy credits for your organization to keep working.": "为您的组织购买额度以继续工作。",
  "Buy credits to keep working": "购买额度以继续工作",
  "Buy credits to keep working.": "购买额度以继续工作。",
  "Buy extra usage": "购买额外用量",
  "Buy extra usage so people in your organization can keep using Claude if they hit a limit.": "购买额外用量，以便您组织中的成员在达到限额后仍能继续使用 Claude。",
  "Buy extra usage so people in your organization can keep using Claude when they hit a plan limit. Your organization’s monthly spend limit still applies.": "购买额外用量，让您的组织成员在达到套餐限额时仍可继续使用 Claude。您组织的每月支出限额仍然适用。",
  "Buy extra usage so you can keep using Claude when you hit a plan limit.": "购买额外用量，以便在达到套餐限制时仍可继续使用 Claude。",
  "Buy extra usage to get started": "购买额外用量以开始使用",
