  "Calls": "调用",
  "Calls are made with your connected account. Tool annotations are self-reported by the server and not verified by Anthropic — connect a test account with representative data where possible. Write/destructive tools are never called. Snippets of the tool responses are saved with your submission for Anthropic reviewers, so don't run this against a server holding real customer data.": "调用使用你已连接的账户进行。工具注解由服务器自行报告，未经 Anthropic 验证——请尽可能连接一个包含代表性数据的测试账户。写入/破坏性工具绝不会被调用。工具响应的片段会随你的提交一起保存，供 Anthropic 审核人员查看，因此请勿针对持有真实客户数据的服务器运行此操作。",
  "Calls are made with your connected account. Tool annotations are self-reported by the server and not verified by Anthropic — connect a test account with representative data where possible. Write/destructive tools are never called. Snippets of the tool responses are saved with your submission for Anthropic reviewers, so don’t run this against a server holding real customer data.": "调用会使用您连接的账户。工具标注由服务器自行报告，Anthropic 不作验证——请尽可能连接一个带有代表性数据的测试账户。写/破坏性工具从不被调用。工具响应的片段会随您的提交一起保存供 Anthropic 审核人员查看，因此请勿对存放真实客户数据的服务器运行此操作。",
