  "Canceling now means you are no longer receiving a promotion. If you resubscribe you’ll get the standard rate.": "现在取消意味着您将不再享受促销优惠。如果您重新订阅，将按标准费率计费。",
  "Canceling will immediately remove your {productName} access. Your last unpaid invoice will no longer be due and recurring billing will stop. You may resubscribe at any time.": "取消将立即移除您的 {productName} 访问权限。您最后一笔未付账单将不再到期，且周期性计费将停止。您可以随时重新订阅。",
