  "Cannot remove the last domain. At least one domain must remain.": "无法移除最后一个域名。必须保留至少一个域名。",
  "Cannot remove the last range while the allowlist is enabled. Disable the allowlist first.": "启用允许列表时无法移除最后一个范围。请先禁用允许列表。",
  "Canva": "Canva",
