  "Canvas is managed by Anthropic": "Canvas 由 Anthropic 管理",
  "Canvas setup is ambiguous for this organization. Ask your administrator to check the LTI configuration.": "此组织的 Canvas 设置不明确。请让您的管理员检查 LTI 配置。",
  "Can’t access cloud-synced folder": "无法访问云同步文件夹",
  "Can’t access this organization": "无法访问此组织",
