  "Can’t check right now": "现在无法检查",
  "Can’t check your branch": "无法检查您的分支",
  "Can’t confirm it’s closed": "无法确认它已关闭",
  "Can’t determine the current version. Make {to} current so everyone gets it? This could be an older version than members have now.": "无法确定当前版本。要将 {to} 设为当前版本供所有人使用吗？它可能比成员现在使用的版本更旧。",
  "Can’t determine the current version. Make {to} current? This could be an older version than you’re on now.": "无法确定当前版本。要将 {to} 设为当前版本吗？它可能是比您现在所用更旧的版本。",
  "Can’t determine the current version. Roll back so everyone gets {to}?": "无法确定当前版本。是否回滚，让所有人得到 {to}？",
  "Can’t determine the current version. Roll back to {to}?": "无法确定当前版本。回滚到 {to}？",
  "Can’t determine which sandbox holds this file.": "无法确定哪个沙盒持有此文件。",
  "Can’t find your organization? Check your email for an invitation to join or contact your organization’s admin to request access.": "找不到您的组织？请检查您的电子邮箱是否有加入邀请，或联系您的组织管理员申请访问权限。",
  "Can’t load this channel’s configuration": "无法加载此频道的配置",
  "Can’t move this task because cloud tasks run at most once per hour.": "无法移动此任务，因为云任务每小时最多运行一次。",
  "Can’t move this task because it also runs from the API or GitHub. Moving would delete that trigger.": "无法移动此任务，因为它也通过 API 或 GitHub 运行。移动会删除该触发器。",
  "Can’t move this task because it has pattern-scoped tool approvals.": "无法移动此任务，因为它包含按模式限定的工具审批。",
  "Can’t move this task because it notifies a local dispatch session.": "无法移动此任务，因为它会通知本地调度会话。",
  "Can’t move this task because it uses Claude in Chrome.": "无法移动此任务，因为它使用了 Chrome 中的 Claude。",
  "Can’t move this task because it uses a local working directory.": "无法移动此任务，因为它使用本地工作目录。",
  "Can’t move this task because it uses local folders or files.": "无法移动此任务，因为它使用本地文件夹或文件。",
  "Can’t move this task because its file couldn’t be read.": "无法移动此任务，因为无法读取其文件。",
  "Can’t move this task because its folder access can’t come with it. To run it on this computer, create a new task and pick its folders again.": "无法移动此任务，因为其文件夹访问权限无法随行。要在此计算机上运行，请新建任务并重新选择其文件夹。",
  "Can’t move this task because its instructions couldn’t be read.": "无法移动此任务，因为无法读取其指令。",
  "Can’t move this task because its schedule isn’t a supported preset.": "无法移动此任务，因为其计划不是受支持的预设。",
  "Can’t move this task because its schedule isn’t a supported preset. To run it on this computer, create a new task with a standard schedule.": "无法移动此任务，因为它的计划不是受支持的预设。要在这台电脑上运行，请创建一个采用标准时间表的新任务。",
  "Can’t move this task because its schedule isn’t supported.": "无法移动此任务，因为不支持其计划安排。",
  "Can’t move this task because its schedule isn’t supported. To run it on this computer, create a new task with a standard schedule.": "无法移动此任务，因为不支持其计划安排。要在这台计算机上运行它，请创建一个采用标准计划的新任务。",
  "Can’t move this task because it’s connected to a project. To run it on this computer, create a new task instead.": "无法移动此任务，因为它已连接到某个项目。要在这台电脑上运行，请新建一个任务。",
  "Can’t move this task because it’s triggered from the API or GitHub, not on a schedule.": "无法移动此任务，因为它是从 API 或 GitHub 触发的，而不是按计划触发的。",
  "Can’t move this task yet. Moving would disconnect it from its projects. To run it in the cloud, create a new task instead.": "暂时无法移动此任务。移动会使它与所属项目断开连接。要在云端运行，请新建一个任务。",
  "Can’t open this chat": "无法打开此聊天",
  "Can’t reach Claude": "无法连接到 Claude",
  "Can’t reach Claude. Check your connection and try again.": "无法连接到 Claude。请检查你的连接并重试。",
  "Can’t reach GitHub — check your connection.": "无法连接 GitHub——请检查您的连接。",
  "Can’t reach session": "无法连接到会话",
  "Can’t reach the Claude API from Claude’s workspace.": "无法从 Claude 的工作区访问 Claude API。",
  "Can’t reach this host": "无法访问此主机",
  "Can’t reach your computer": "无法连接到您的计算机",
  "Can’t reach your inference provider ({host}) from Claude’s workspace.": "无法从 Claude 的工作区连接到您的推理服务提供方（{host}）。",
  "Can’t reach your organization’s plugin server — showing locally-provisioned plugins below; installs are paused until the connection is restored.": "无法连接您组织的插件服务器——下方显示的是本地配置的插件；在连接恢复之前，安装将暂停。",
