  "Can’t start this in the cloud. Cloud sessions are turned off for your organization. You can start it here instead.": "无法在云端启动此任务。您的组织已关闭云会话。您可以改为在此处启动。",
  "Can’t start this in the cloud. No cloud environment is set up for this repository. You can start it here instead.": "无法在云中启动。尚未为此仓库设置任何云环境。您可以改为在此处启动。",
