  "Catch me up on Slack": "帮我快速了解 Slack 上的最新情况",
  "Catch me up on Slack: summarize what’s happened in my most active channels since yesterday and flag the messages that look like they’re waiting on a reply from me. Start with whatever looks most urgent.": "帮我跟进 Slack：总结我那些最活跃的频道自昨天以来发生的事情，并标出那些看起来在等回复的消息。从看起来最紧急的开始。",
  "Catch me up on Teams": "帮我在 Teams 上补上进度",
  "Catch me up on a legal area": "帮我快速了解一个法律领域",
  "Catch me up on a research area I name: search for what’s happened in the last year — the notable results, what’s gaining acceptance, what’s being challenged — then ask me what I work on and pull out the three developments that matter most for my own work.": "帮我快速了解我指定的某个研究领域：搜索过去一年发生的事情——重要的结果、逐渐被接受的观点、受到挑战的观点——然后问我做的是什么，并挑出与我的工作最相关的三项进展。",
  "Catch me up on my Teams messages: summarize this week’s active conversations, flag anything waiting on me, and list any decisions that got made while I wasn’t looking.": "帮我跟进一下 Teams 上的消息：总结本周活跃的对话，标出任何在等我的内容，并列出我没看到时已做出的决定。",
  "Catch me up on my field": "帮我了解我所在领域的近况",
  "Catch me up on what happened in my channels over the weekend — decisions, announcements, anything addressed to me. Then offer to run this catch-up automatically every Monday morning.": "帮我在频道上补上周末发生的事——决策、公告、任何发给我的内容。然后提议每周一早上自动运行这次补进度。",
  "Catch me up on what’s changed in a legal area I name — privacy, employment, AI rules, whatever matters to me — research the latest rules, cases, and enforcement moves, then write me a dated, plain-English memo on what changed and what to do differently.": "帮我快速了解某个我指定的法律领域近期有哪些变化——隐私、雇佣、AI 规则，任何我关心的——研究最新的法规、案例和执法动向，然后写一份带日期、用通俗英文写成的备忘录，说明发生了什么变化以及该作出哪些不同的应对。",
