  "Check my most recent Figma file for consistency: colors, text styles, and spacing values that drift from the rest of the file. Give me a fix list ordered by how visible each issue is.": "检查我最近的 Figma 文件的一致性：颜色、文本样式和间距值是否偏离了文件其余部分。给我一份按问题明显程度排序的修复清单。",
