  "Check that <code>gh</code> is installed and authenticated.": "请检查 <code>gh</code> 是否已安装并完成身份验证。",
  "Check that computer use is turned on in the Claude desktop app on the computer this task is using (Settings → Computer use), then continue.": "请确认此任务所用电脑上的 Claude 桌面应用已开启计算机使用功能（设置 → 计算机使用），然后继续。",
  "Check that computer use is turned on in the Claude desktop app on {device} (Settings → Computer use), then continue.": "请检查 {device} 上的 Claude 桌面应用是否已开启计算机使用（设置 → 计算机使用），然后继续。",
  "Check that my experiment can detect what I’m looking for: I’ll describe the design in two sentences — you estimate a plausible effect-size range, run the power math with every assumption visible, and tell me the sample size that makes reviewers stop asking.": "检查我的实验能否检测出我想要的结果：我会用两句话描述设计——你来估算一个合理的效应量范围，把每一步假设都摆在明面上做完功效计算，并告诉我能让审稿人不再追问的样本量。",
  "Check that your SSH host or local proxy is reachable, then try again.": "请检查你的 SSH 主机或本地代理是否可达，然后重试。",
  "Check the credential works before saving.": "保存前请检查凭据是否可用。",
  "Check the disk’s free space and the session folder’s permissions, then try again.": "请检查磁盘的可用空间和会话文件夹的权限，然后重试。",
