  "Check today’s action items": "查看今天的待办事项",
  "Check today’s meetings for action items assigned to me and list them with deadlines where mentioned. If it’s useful, set this sweep to run automatically every evening.": "检查今天的会议中分配给我的待办事项，并列出其中提到的截止日期。如果有用，请将这个检查设置为每天傍晚自动运行。",
  "Check tomorrow’s weather and tell me if I need an umbrella.": "查看明天的天气，告诉我是否需要带伞。",
  "Check watched artifacts": "检查已关注的构件",
