  "Choose where to save this project on your computer.": "选择在您电脑上保存此项目的路径。",
  "Choose whether Claude in Chrome works on all sites by default": "选择 Chrome 中的 Claude 是否默认在所有网站上运行",
  "Choose whether to add your transcript to the public archive": "选择是否将您的对话记录添加到公开归档",
  "Choose whether to create a new organization or upgrade an existing one.": "选择是创建一个新组织，还是升级现有组织。",
  "Choose whether {productName} works on all sites by default": "选择 {productName} 默认是否对所有站点生效",
  "Choose which Claude models members can use. This applies to Chat, Cowork, Claude Code, Claude Tag, Office Agents, Claude Design, and Claude Science. <pricingLink>See model performance and pricing</pricingLink>": "选择成员可以使用哪些 Claude 模型。适用于 Chat、Cowork、Claude Code、Claude Tag、Office Agents、Claude Design 和 Claude Science。<pricingLink>查看模型性能与定价</pricingLink>",
  "Choose which Claude models members can use. This applies to Chat, Cowork, Claude Code, Claude Tag, Office Agents, and Claude Design. <pricingLink>See model performance and pricing</pricingLink>": "选择成员可以使用的 Claude 模型。这适用于聊天、Cowork、Claude Code、Claude Tag、Office Agents 和 Claude Design。<pricingLink>查看模型性能与定价</pricingLink>",
  "Choose which domains the sandbox can access": "选择沙箱可以访问的域名",
  "Choose which environment or runner pool Claude Code sessions use by default, and whether Anthropic-hosted environments are offered.": "选择 Claude Code 会话默认使用哪个环境或运行器池，以及是否提供 Anthropic 托管的环境。",
  "Choose which items appear in your sidebar.": "选择侧边栏中显示的项目。",
  "Choose which models your organization can use, and the highest effort level they can run at. Setting a maximum effort level is optional. <pricingLink>See model performance and pricing</pricingLink>": "选择您的组织可以使用哪些模型，以及它们可运行的最高努力级别。设置最大努力级别是可选的。<pricingLink>查看模型性能和定价</pricingLink>",
  "Choose which spend limit to use in the event that a member belongs to multiple groups.": "选择当成员属于多个组时使用哪个支出限制。",
