  "Connect Gmail": "连接 Gmail",
  "Connect Gmail and triage my inbox: group everything that still needs me by urgency, give me a one-line summary of each, then draft replies for the two that most need answering today — drafts only, for me to review and send myself. If Gmail isn’t connected, walk me through connecting it first.": "连接 Gmail 并整理我的收件箱：按紧急程度对所有仍需我处理的内容分组，给我每个的一行摘要，然后为今天最需要回复的两封起草回复——只起草，由我自己审核并发送。如果 Gmail 未连接，先带我完成连接。",
  "Connect Gmail so you can help with my inbox, starting with my unread emails.": "请连接 Gmail 以便处理我的收件箱，从我的未读邮件开始。",
  "Connect Google Drive": "连接 Google Drive",
