  "Connect Google Drive with me — show me where to click. Then find the documents people shared with me this past week, summarize each in two lines, and tell me which ones need something from me versus which I can skip. Finish with my three most recently edited docs and what looks unfinished in each.": "和我一起连接 Google Drive — 告诉我该点击哪里。然后找出过去一周别人分享给我的文档，每份用两行话概括，并告诉我哪些需要我处理、哪些可以跳过。最后列出我最近编辑过的三份文档，以及每份里看起来尚未完成的内容。",
