  "Connected without signing in: OAuth is configured for this server, but the server accepted the connection without requesting authentication. If the server is expected to require sign-in, check its auth enforcement.": "未登录即已连接：此服务器已配置 OAuth，但服务器在没有要求身份验证的情况下接受了连接。如果该服务器本应要求登录，请检查其身份验证强制策略。",
