  "Connected, but the identity provider didn't issue a refresh token. This connector will stop working when the access token expires. For OIDC providers, add 'offline_access' to the scope; for others, see your IdP's documentation.": "已连接，但身份提供方未颁发刷新令牌。当访问令牌过期时，此连接器将停止工作。对于 OIDC 提供方，请在范围中添加 'offline_access'；其他情况请参阅您 IdP 的文档。",
  "Connected, but the identity provider didn’t issue a refresh token. This connector will stop working when the access token expires. For OIDC providers, add ‘offline_access’ to the scope; for others, see your IdP’s documentation.": "已连接，但身份提供方未颁发刷新令牌。当访问令牌过期时，此连接器将停止工作。对于 OIDC 提供方，请在作用域中添加 ‘offline_access’；对于其他情况，请参阅您的 IdP 文档。",
  "Connected. This host is ready to use.": "已连接。此主机已可以使用。",
  "Connecting": "连接中",
  "Connecting GitHub automatically tries to link every account your GitHub login can access. These couldn’t be linked:": "连接 GitHub 时会自动尝试链接您的 GitHub 登录可访问的每个账户。以下账户无法链接：",
  "Connecting GitHub for your organization isn’t available in the desktop app. Open claude.ai in your web browser and connect from the GitHub page in admin settings.": "桌面应用中无法为您的组织连接 GitHub。请在网页浏览器中打开 claude.ai，并在管理设置的 GitHub 页面中进行连接。",
  "Connecting doesn’t give Claude repo access. You’ll install the Claude GitHub App when you choose a repo.": "建立连接并不会让 Claude 获得仓库访问权限。当您选择仓库时，您将安装 Claude GitHub App。",
