  "Connecting to {server}...": "正在连接到 {server}...",
  "Connecting to “{host}” reaches a machine Claude hasn’t connected to before, so its key hasn’t been checked yet — nothing is wrong with the settings. Connect, and Claude will show you that machine’s key fingerprint to confirm before it goes any further.": "连接到“{host}”会到达一台 Claude 之前未曾连接过的机器，因此其密钥尚未经过检查——设置没有任何问题。连接后，Claude 会在继续之前向您显示该机器的密钥指纹以供确认。",
  "Connecting to “{host}” timed out before the SSH handshake finished. Usually the host or port is not reachable from this network, or the path to it is slow — check your VPN or firewall and that the machine is on, then try again.": "连接“{host}”在 SSH 握手完成前超时。通常是从该网络无法访问主机或端口，或到它的链路缓慢——请检查您的 VPN 或防火墙以及该机器是否开机，然后重试。",
