  "Connectors have moved to Customize. Head to the new Customize page to manage your skills and connectors.": "连接器已移至“自定义”。请前往新的“自定义”页面管理您的技能和连接器。",
  "Connectors let Claude work with your team’s tools and data.": "连接器让 Claude 可以使用您团队的工具和数据。",
  "Connectors let Claude work with your team’s tools and data. Add them from the directory, or add a custom one.": "连接器让 Claude 可以使用您团队的工具和数据。可从目录中添加，也可以添加自定义连接器。",
  "Connectors let Claude work with your team’s tools and data. Add them from the directory.": "连接器让 Claude 能使用您团队的工具和数据。请从目录中添加。",
  "Connectors let me read the same docs, email and threads you do, but they aren’t switched on for this deployment. You can skip this step.": "连接器让我能读取与您相同的文档、邮件和会话串，但此部署尚未启用连接器。您可以跳过此步骤。",
  "Connectors let me read the same docs, email and threads you do. Your admin hasn’t enabled any from the directory for your team yet; you can come back to this anytime from the + menu in a chat.": "连接器让我能读取与您相同的文档、邮件和讨论串。您的管理员尚未从目录为您的团队启用任何连接器；您可以随时从对话中的 + 菜单回到这里。",
  "Connectors let me read the same docs, email and threads you do. Your admin hasn’t enabled any yet — ask for the ones your team uses and I’ll be ready when they land.": "连接器让我能读取与您相同的文档、邮件和会话串。您的管理员尚未启用任何连接器——请申请您团队在用的那些，它们一上线我就准备就绪。",
  "Connectors let your agent access external tools and data sources.": "连接器让您的智能体能访问外部工具和数据源。",
  "Connectors like Google Workspace, email, and calendar": "如 Google Workspace、电子邮件和日历等连接器",
