  "Country": "国家/地区",
  "Counts reflect when findings were first detected by a scan. This doesn't necessarily reflect when the vulnerability was introduced. An increase may include pre-existing issues found for the first time.": "计数反映的是发现项首次被扫描检测到的时间。这不一定反映漏洞被引入的时间。增加的部分可能包括首次被发现的已有问题。",
  "Counts show findings that are currently open, with no time filter. The +/- changes cover the selected period; the trend chart covers the same period, capped at the last 30 days. Both are based on when a scan first detected each finding, not when the vulnerability was introduced. An increase can include pre-existing issues found for the first time.": "计数显示当前未关闭的发现，未应用时间过滤。+/- 变化涵盖所选时间段；趋势图涵盖同一时间段，最多回溯最近 30 天。两者均基于扫描首次发现各项问题的时间，而不是漏洞引入的时间。增加量可能包含首次被发现的既有问题。",
  "Coupon applied. {percentOff}% off Max 20x for {durationInMonths, plural, one {# month} other {# months}}.": "优惠券已应用。Max 20x 享受 {percentOff}% 折扣，有效期为 {durationInMonths, plural, one {# 个月} other {# 个月}}。",
