  "Covers data retention, chat and connector sharing, public projects, location metadata, and feedback collection. Manage access also enables data and audit log exports.": "涵盖数据留存、聊天和连接器共享、公开项目、位置元数据以及反馈收集。开启管理访问权限后，还可以导出数据和审计日志。",
  "Covers organization usage analytics and activity dashboards.": "涵盖组织使用分析和活动仪表板。",
  "Covers plans, invoices, payment methods, usage and cost reports, spend limits, and overage approvals.": "涵盖套餐、发票、付款方式、用量和成本报告、支出限额以及超额审批。",
