  "Create three brand directions for my company — name treatment, color palette, type pairing, and the vibe in one sentence each — then draw the strongest as a simple SVG logo I can actually use. Tell me the company in one line, or demo on an invented one.": "为我的公司创建三个品牌方向——名称处理、配色方案、字体搭配，以及各用一句话描述的氛围——然后将最强的那个画成一个我实际能用的简单 SVG 标志。请用一句话告诉我公司名称，或者用一个虚构的公司来演示。",
