  "Creates a new artifact on claude.ai from the artifact type below, with the file below as its data. Its page was written by that type’s publisher; the new artifact stays private until you share it.": "在 claude.ai 上根据下方的构件类型创建新构件，并以下方的文件作为其数据。其页面由该类型的发布者编写；新构件在您共享之前保持私密。",
  "Creates a new artifact on claude.ai from the artifact type below. Its page was written by that type’s publisher and no file is uploaded from this task; the new artifact stays private until you share it.": "在 claude.ai 上根据下方的构件类型创建新构件。其页面由该类型的发布者编写，此任务不会上传任何文件；新构件在您分享之前保持私密。",
  "Creates a priority-100 rule that allows requests to the listed hosts and injects this credential. Uncheck to attach the credential from an existing or custom rule instead.": "创建一个优先级为 100 的规则，允许向列出的主机发送请求并注入此凭证。取消勾选则改为从现有或自定义规则附加该凭证。",
  "Creates tables for what you describe below and swaps any local-only state to real reads and writes. If a database isn't configured for this project yet, Claude will provision one first.": "为您在下面描述的内容创建表，并将任何仅本地状态交换为真实的读写。如果尚未为此项目配置数据库，Claude 将首先配置一个。",
