  "Design (opens in your browser)": "Design（在您的浏览器中打开）",
  "Design Tools and Creative Applications Powered by Claude AI": "由 Claude AI 驱动的设计工具和创意应用程序",
  "Design UI/UX wireframes": "设计 UI/UX 原型图",
  "Design a CRISPR knockout screen": "设计 CRISPR 敲除筛选",
  "Design a LinkedIn banner in Canva that would make my profile look sharp — abstract, professional, modern, no text needed. Make two variants so I can pick, and export the one I choose.": "在 Canva 中设计一个能让我的个人资料更显锐利的 LinkedIn 横幅——抽象、专业、现代，不需要文字。做两个变体供我挑选，并导出我选择的那个。",
  "Design a chracter profile based on my creative super power": "根据我的创意超能力设计角色资料",
  "Design a digital pet that grows based on my coding habits": "设计一个根据我的编码习惯成长的数字宠物",
  "Design a filing system for my teaching materials — the folder tree, naming rules that sort correctly by unit and year, and a ten-minute weekly reset ritual — shown filled with realistic example filenames first. Then adjust it to how my courses actually run.": "为我的教学资料设计一套归档系统——文件夹树、能按单元和年份正确排序的命名规则，以及一个十分钟的每周重置流程——先用真实的示例文件名展示填好后的样子。然后根据我课程的实际运行方式调整它。",
  "Design a game that teaches coding concepts through storytelling": "设计一个通过讲故事讲授编程概念的游戏",
  "Design a landing page concept in front of me: I’ll name the product, or you invent one worth practicing on — build an interactive mockup with layout, type, and color, and explain each choice as you make it.": "在我面前设计一个落地页概念：我会说出产品名，或者你虚构一个值得练习的——构建一个带布局、字体和颜色的交互式原型，并在每个选择时解释你的考量。",
  "Design a landing page in front of me": "在我面前设计一个落地页",
  "Design a learning challenge that pushes my creative boundaries": "设计一个挑战我创造力极限的学习挑战",
  "Design a lesson or curriculum": "设计课程或教学大纲",
  "Design a lightweight performance review process for a team my size — ask my headcount and culture, then propose the cadence, the actual form with its questions, and how to calibrate fairly.": "为我这种规模的团队设计一个轻量级的绩效考核流程——先问我人数和文化，然后提议考核频率、实际使用的表格及其问题，以及如何公平校准评分。",
  "Design a lightweight review cycle": "设计一个轻量的评审周期",
  "Design a metrics dashboard for a problem I describe — which charts, which cuts, what belongs top-left — then build a working version with sample data so I can see it rather than imagine it.": "为我描述的问题设计一个指标仪表盘——用哪些图表、哪些切分维度、什么放在左上角——然后用示例数据构建一个可工作的版本，让我能直接看到效果而不是凭空想象。",
  "Design a metrics framework": "设计一个指标框架",
  "Design a portfolio dashboard": "设计一个作品集仪表盘",
  "Design a presentation layout": "设计演示文稿布局",
  "Design a printable weekly planner page in Canva — space for top three priorities, a day-by-day schedule, and notes — minimal enough that I’d actually print and use it.": "在 Canva 中设计一页可打印的周计划表——预留最重要的三件事、逐日日程和笔记的空间——极简到我真会打印出来使用。",
  "Design a research study": "设计一项研究",
  "Design a software architecture": "设计软件架构",
  "Design a strategy game based on my business challenges": "根据我的业务挑战设计一个策略游戏",
  "Design a strategy inspired by patterns found in nature": "从大自然的模式中获取灵感设计一个策略",
  "Design a study": "设计一项研究",
  "Design a study with me and write it down: ask my question, population, and constraints, then produce a one-page design — variables, controls, sample-size logic, threats to validity, and the analysis plan.": "和我一起设计一项研究并写下来：先问我的研究问题、人群和限制条件，然后产出一份一页纸的设计——变量、对照、样本量逻辑、对效度的威胁以及分析计划。",
  "Design a system with me": "和我一起设计一个系统",
  "Design a weekly planner": "设计一个每周计划表",
  "Design an A/B test end to end right now — demo on raising signup conversion on a landing page unless I give my metric and traffic — sample-size math shown, runtime, and the three mistakes that would invalidate it. Then ask for my numbers.": "现在就完整设计一次 A/B 测试——如果我没有给出指标和流量，就以提升落地页注册转化率为示例，展示样本量计算、运行时间以及三种会使结果失效的错误。然后询问我的数据。",
  "Design an experience that changes how people perceive time": "设计一项改变人们时间感知的体验",
  "Design an experience that transforms digital connections into physical ones": "设计一种能将数字连接转化为物理连接的体验",
  "Design an experiment": "设计一个实验",
  "Design an experiment with me and produce the protocol: ask my hypothesis and constraints, then write it — conditions, controls, group sizes with the power logic, measures, and the analysis plan.": "和我一起设计一项实验并写出方案：先问我的假设和限制条件，然后把它写出来——条件、对照、带统计功效逻辑的分组大小、测量指标以及分析计划。",
