  "Design the figure before I fight the plotting library: I describe a result in one sentence, you pick the right chart type, sketch the figure with labels and caption, and write the Python that renders it — demoing on an invented result if I’m blank.": "在我和绘图库较劲之前先把图设计好：我用一句话描述一个结果，你选出合适的图表类型，画出带标签和图注的草图，并写出渲染它的 Python 代码——如果我一时没思路，就用一个虚构结果做示范。",
