  "Draft something for me": "帮我起草内容",
  "Draft the Q3 board deck": "起草第三季度董事会材料",
  "Draft the UX writing for a flow I describe — onboarding, checkout, empty states — every button, headline, and error message in a tone I pick, as a table I can hand over.": "为我描述的一个流程起草 UX 文案——新手引导、结账、空状态——用我选定的语气写出每一个按钮、标题和错误信息，整理成我可以交接的表格。",
  "Draft the email I keep putting off": "起草我一直拖延的那封邮件",
  "Draft the email I keep putting off. Ask me two quick things — who it’s to and what I need from them — then write it three ways: warm, direct, and diplomatic-but-firm. Tell me which you’d send, and I’ll tweak it with you.": "帮我起草那封我一直拖延的邮件。问我两个小问题——收件人是谁、我需要从他们那里得到什么——然后用三种方式写出来：热情、直接，以及委婉但坚定。告诉我你会发送哪一版，我会和你一起微调。",
  "Draft the follow-up notes for my last meeting: a short summary, decisions, and an action list with owners — written so I could send it to the attendees exactly as-is.": "为我上一次会议草拟后续记录：一份简短摘要、各项决策，以及带负责人的行动清单——写得让我可以原样发送给参会者。",
  "Draft the proposal that closes my first deal, directly in your reply — context, the problem in the client’s words, approach, timeline, price framing, and the next step — from a one-line description of the deal. Default: a paid pilot with a small business.": "直接在你的回复中起草能帮我拿下第一笔交易的提案——背景、用客户的话描述的问题、方案、时间表、价格框架，以及下一步——根据一行交易描述生成。默认示例：面向小企业的付费试点。",
  "Draft the proposal that wins the next engagement, directly in your reply — context, the client’s problem in their words, approach, workplan summary, fees framing, and next step. Default: a pricing study for a mid-size retailer; I’ll reshape it to my deal.": "直接在你的回复中起草一份能赢得下一个项目的提案——背景、客户用自己的话描述的问题、方法、工作计划摘要、费用框架和下一步。默认场景：为一家中型零售商做定价研究；我会把它改成适合我的交易。",
  "Draft the storyline before the deck": "在制作幻灯片之前先起草叙事主线",
  "Draft tomorrow’s agendas": "起草明天的议程",
  "Draft · in your voice": "草稿 · 用您的语气",
