  "Duration": "时长",
  "During high demand, Claude keeps replies short so you can chat longer.": "在高峰时期，Claude 会保持简短的回复，以便您可以聊得更久。",
  "During spin up there may be delays in release into the directory.": "启动期间，目录发布可能会有延迟。",
  "During this process, you won’t be able to modify these settings:": "在此过程中，您将无法修改以下设置：",
  "Dynamic Client Registration (DCR). Works with most servers.": "动态客户端注册（DCR）。适用于大多数服务器。",
  "Dynamic workflows": "动态工作流",
  "Dynamic workflows are disabled by your organization's policy.": "动态工作流已被你组织的政策禁用。",
  "Dynamic workflows are disabled by your organization’s policy.": "动态工作流已被您组织的策略禁用。",
  "Dynamic workflows let Claude fan out to many subagents on a single task": "动态工作流让 Claude 在单个任务上分散调用多个子智能体",
  "Dynamic workflows run many subagents in parallel and can use a lot of your usage limit. Stop them any time from the <link>tasks pane</link>.": "动态工作流会并行运行多个子代理，可能消耗大量用量限额。您可以随时在<link>任务面板</link>中停止它们。",
  "Dynamic workflows run many subagents in parallel and can use a lot of your usage limit. Stop them any time from the <link>tasks panel</link>.": "动态工作流会并行运行许多子智能体，可能会消耗大量用量限额。你可以随时从 <link>任务面板</link> 中停止它们。",
  "Dyslexic friendly": "读写困难症友好",
  "Dyslexic friendly chat font": "对读写困难者友好的聊天字体",
  "E-commerce manager": "电商经理",
  "EAP": "EAP",
  "EBITDA": "EBITDA",
  "ELIGIBLE TO JOIN": "符合加入条件",
  "EMT": "急救医疗员",
  "EPS": "EPS",
  "EPS Est": "每股收益预估",
  "ESL teacher": "英语作为第二语言（ESL）教师",
  "Each URL needs a label users will recognize, like a region or data center name.": "每个 URL 都需要一个用户能识别的标签，例如区域或数据中心名称。",
  "Each account is limited to one Team organization with nonprofit pricing.": "每个账户仅限一个享受非营利定价的 Team 组织。",
  "Each billed category’s share of Claude’s channel spend for the selected period. Direct messages aren’t included, and monitoring isn’t billed, so neither counts toward the percentages. Figures are approximate and may shift as usage is categorized; see your invoice and the Spend by channel table for exact amounts.": "所选期间内 Claude 各计费类别在渠道支出中所占的份额。私信不计入，监控不计费，因此两者均不计入百分比。数字为近似值，可能随用量归类而变化；确切金额请参阅您的发票和“按渠道支出”表。",
  "Each exposed tool has a clear name, description, and example usage.": "每个暴露的工具都应有清晰的名称、描述和使用示例。",
  "Each guest pass is a free week of Pro. <termsLink>Terms apply</termsLink>": "每张访客通行证为一周免费 Pro。<termsLink>适用条款</termsLink>",
  "Each guest pass is a free week. If they love it and subscribe, you’ll get {rewardAmount} in usage credits. <termsLink>Terms apply</termsLink>": "每张访客通行证为一周免费。如果他们喜欢并订阅，您将获得 {rewardAmount} 的用量额度。<termsLink>适用条款</termsLink>",
  "Each model is available only in the products that support it.": "每个模型仅在支持它的产品中可用。",
  "Each parameter is injected into the request body at the given JSON path or form key. Authorization headers and any query/body key matching a parameter name are stripped before injection. Requests whose body or query already contains a key that collides with a parameter name under common normalizations (e.g. api_key[] or api.key vs api_key) are rejected with 502 to prevent credential substitution.": "每个参数都会按给定的 JSON 路径或表单键注入到请求体中。授权头以及任何与参数名匹配的查询/正文键会在注入前被剔除。如果请求的正文或查询中已包含在常见规范化下与参数名冲突的键（例如 api_key[] 或 api.key 与 api_key），会被以 502 拒绝，以防止凭据替换。",
  "Each person gets an invitation email when you select Send invites.": "当您选择“发送邀请”时，每个人都会收到一封邀请电子邮件。",
  "Each row is a placement mounted on this page and the gate that stopped it (or what it picked). Click to see why each candidate was filtered.": "每一行都是挂载到此页面上的一个投放位，以及阻止它（或它选取的内容）的门槛。点击可查看每个候选项被过滤的原因。",
  "Each row’s share of total Claude Tag spend in the period, including direct messages and unattributed usage, so rows don’t sum to 100%. Direct messages are never rows; unattributed usage is the No channel row.": "每一行在此期间总 Claude Tag 支出中的占比，包括直接消息和未归因的用量，因此各行相加不等于 100%。直接消息从不作为行；未归因用量是“无频道”行。",
  "Each run continues this session": "每次运行都会延续此会话",
  "Each run starts a fresh session": "每次运行都会开启一个全新的会话",
  "Each session keeps its own": "每个会话各自保留",
  "Each session keeps its own cookies": "每个会话保留自己的 Cookie",
  "Each step makes Claude noticeably more useful.": "每一步都会让 Claude 明显更有用。",
  "Each subagent runs its own requests. Be deliberate about spawning them, and consider configuring a cheaper model for simpler subagents.": "每个子代理都会独立发起请求。请慎重创建子代理，并考虑为较简单的子代理配置更便宜的模型。",
  "Each subagent runs its own requests. Consider a cheaper model for simple subagents, or tighten their prompts.": "每个子代理都会独立发起请求。对于简单的子代理，可以考虑使用更便宜的模型，或收紧它们的提示词。",
  "Each team member's Claude can remember context from their own past chats. Memory stays private to each person. <a>Learn more</a>": "每个团队成员的 Claude 都可以记住来自其过去聊天的上下文。记忆对每个人保持私密。<a>了解更多</a>",
  "Each team member’s Claude can remember context from their own past chats. Memory stays private to each person. <a>Learn more</a>": "每位团队成员的 Claude 都可以记住自己过去聊天中的上下文。记忆仅对各自个人可见。<a>了解更多</a>",
  "Each user has a different set of prompts": "每个用户有不同的一组提示词",
  "Each user has a different set of resources": "每个用户拥有不同的资源集",
  "Each user has a different set of tools": "每个用户都有一组不同的工具",
  "Each user or tenant connects to a unique URL.": "每个用户或租户连接到唯一的 URL。",
  "Each user signs in through the server’s OAuth flow before they can use any tools or resources.": "每位用户都需要通过服务器的 OAuth 流程登录，然后才能使用任何工具或资源。",
  "Earlier messages are kept on the remote machine and couldn’t be loaded from it just now. That usually means it couldn’t be reached, not that they’re gone. Make sure this environment is connected (open or resume a session on it), then retry.": "较早的消息保留在远程机器上，刚刚无法从中加载。这通常意味着该机器无法访问，而不是消息已丢失。请确保此环境处于连接状态（在其上打开或恢复会话），然后重试。",
  "Earlier messages aren't shown — this conversation is too large to load in full.": "较早的消息未显示——此对话太大，无法完整加载。",
  "Earlier messages aren’t shown — this conversation is too large to load in full.": "较早的消息未显示——此对话太大，无法完整加载。",
  "Earlier messages aren’t shown. This session is too large to load in full.": "未显示较早的消息。此会话过大，无法完整加载。",
