  "Enabling HIPAA compliance allows you to use PHI within the Eligible Services defined in the BAA. Download the Implementation Guide for configuration requirements, workforce training, and the full list of Eligible Services.": "启用 HIPAA 合规后，您可以在 BAA 中定义的合格服务范围内使用 PHI。请下载实施指南，了解配置要求、员工培训以及合格服务的完整列表。",
  "Enabling HIPAA compliance executes Anthropic's Business Associate Agreement (BAA) and configures this Claude Enterprise organization to handle Protected Health Information (PHI) within the Eligible Services the BAA covers.": "启用 HIPAA 合规将执行 Anthropic 的业务伙伴协议（BAA），并将此 Claude Enterprise 组织配置为在 BAA 涵盖的合资格服务范围内处理受保护健康信息（PHI）。",
  "Enabling HIPAA executes Anthropic’s Business Associate Agreement (BAA) and configures this organization to process Protected Health Information (PHI) within the Eligible Services the BAA covers. You’ll have an opportunity to review the BAA and Anthropic’s Implementation Guide before accepting the terms. If you’ve already accepted Anthropic’s standard BAA for another organization through the self-serve flow, this is the same agreement.": "启用 HIPAA 会执行 Anthropic 的《业务伙伴协议》（BAA），并将此组织配置为在 BAA 涵盖的合格服务内处理受保护健康信息（PHI）。在接受条款前，您将有机会审阅 BAA 和 Anthropic 的实施指南。如果您此前已通过自助流程为另一个组织接受过 Anthropic 的标准 BAA，这是同一份协议。",
  "Enabling auto-merge": "正在启用自动合并",
  "Enabling this capability will grant access to all members assigned to these custom roles. It will also be enabled for all <b>{cap}+ members</b> with the User, Admin, Owner, or Primary owner role.": "启用此功能将向分配给这些自定义角色的所有成员授予访问权限。它也将对所有具有用户、管理员、所有者或主要所有者角色的 <b>{cap}+ 名成员</b> 启用。",
  "Enabling this capability will grant access to all members assigned to these custom roles. It will also be enabled for all <b>{count, plural, one {# member} other {# members}}</b> with the User, Admin, Owner, or Primary owner role.": "启用此能力将向所有分配到这些自定义角色的成员授予访问权限。同时也会为所有具有 User、Admin、Owner 或 Primary owner 角色的 <b>{count, plural, one {# 名成员} other {# 名成员}}</b>启用。",
  "Enabling this capability will grant access to all members assigned to these custom roles. It will also be enabled for all members with the User, Admin, Owner, or Primary owner role.": "启用此功能将向所有被分配这些自定义角色的成员授予访问权。同时也会对所有具有用户、管理员、所有者或主所有者角色的成员启用。",
  "Enabling this capability will grant access to all users assigned to these roles.": "开启此功能将授予分配到这些角色的所有用户访问权限。",
  "Enabling this capability won't grant access to users assigned to custom roles until you also enable it for each role. {link}": "启用此功能后，被分配到自定义角色的用户仍无法访问，除非您也为每个角色分别启用该功能。{link}",
  "Enabling this capability won’t grant access to members assigned to custom roles until you also enable it for each role. {link}": "启用此能力不会向分配到自定义角色的成员授予访问权限，除非您也为每个角色启用它。{link}",
  "Enabling this capability won’t grant access to users assigned to custom roles until you also enable it for each role. {link}": "启用此功能不会授予分配给自定义角色的用户访问权限，除非您也为每个角色启用它。{link}",
