  "Every eligible member in your organization will receive the activation credit email and an in-product nudge.": "您组织中每位符合条件的成员都会收到激活额度邮件和产品内提醒。",
  "Every eligible member in your organization will receive the activation credit email, except the {excludedCount, plural, one {# member} other {# members}} you unchecked.": "组织中每位符合条件的成员都会收到激活额度邮件，但您取消勾选的{excludedCount, plural, one {# 名成员} other {# 名成员}}除外。",
  "Every eligible member in your organization will receive the activation credit email.": "您组织中每位符合条件的成员都会收到激活额度邮件。",
  "Every folder you've worked in appears under Recent — click the `+` next to one to start a session there": "你工作过的每个文件夹都会显示在“最近”下——点击其旁边的 `+` 即可在那里开始一个会话",
  "Every folder you’ve worked in appears under Recent — click the `+` next to one to start a session there": "您工作过的每个文件夹都会出现在“最近”下——点击其中一个旁边的 `+` 即可在那里启动会话",
  "Every host is already covered by an allow rule. Edit that rule after saving this credential to change how it is injected.": "每个主机都已被某条允许规则覆盖。保存此凭据后，编辑该规则即可更改其注入方式。",
