  "Everything you need to teach a great lesson in one place. Start a chat, connect your materials, or update your classroom profile.": "授好一堂课所需的一切都汇集于一处。开始聊天、连接您的教学材料，或更新您的课堂资料。",
  "Everything you need to teach a great lesson in one place—set up by your school. Start a chat, connect your materials, or update your class details.": "上好一堂课所需的一切都集中在一处——由您的学校设置。开始聊天、连接您的教学资料，或更新您的班级详情。",
  "Everything your team has set up is already connected, so I can look in those tools whenever you ask. You can add more anytime from the + menu in any chat.": "您的团队已设置的一切均已连接，因此您随时可以让我查阅这些工具。您可以在任何聊天的 + 菜单中随时添加更多。",
