  "Experimental": "实验性",
  "Experimental. Runs an automated screening of your listing, use cases, and live tool list using Claude. Advisory only — it does not affect whether you can submit.": "实验性功能。使用 Claude 对你的列表、用例和实时工具列表进行自动筛查。仅供参考 — 不影响你能否提交。",
