  "External IdP for gateway sign-in. The user authenticates against this issuer; the resulting token (ID token by default) is sent to the gateway as the Bearer credential. Leave unset only if the gateway is its own OAuth authorization server.": "用于网关登录的外部 IdP。用户针对此颁发者进行认证；生成的 token（默认为 ID token）作为 Bearer 凭据发送到网关。仅当网关本身是其 OAuth 授权服务器时才保持未设置。",
  "External IdP for gateway sign-in. The user’s token from this issuer is sent to the gateway as the Bearer credential.": "用于网关登录的外部 IdP。来自此颁发者的用户令牌将作为 Bearer 凭据发送到网关。",
  "External service that sends SMS messages.": "发送短信的外部服务。",
