  "External services pointing at this URL will stop reaching Conway. \"{label}\" will be permanently removed.": "指向此 URL 的外部服务将停止访问 Conway。\"{label}\" 将被永久删除。",
  "External services pointing at this URL will stop reaching Conway. “{label}” will be permanently removed.": "指向此 URL 的外部服务将无法再访问 Conway。“{label}” 将被永久移除。",
