  "Extra": "额外",
  "Extra HTTP headers sent on every inference request to the configured provider. For tenant routing, org IDs, Bedrock Guardrails, etc.": "在每次向所配置的提供方发起推理请求时发送的额外 HTTP 标头。用于租户路由、组织 ID、Bedrock Guardrails 等。",
  "Extra Usage": "额外用量",
  "Extra headers on every inference request — routing and tenant headers only (org IDs, Bedrock Guardrails). No credentials; use the credential helper for tokens.": "附加到每个推理请求的额外请求头——仅限路由和租户请求头（组织 ID、Bedrock Guardrails）。不含凭据；令牌请使用凭据辅助脚本。",
  "Extra high": "特别高",
  "Extra resource attributes to attach to every span/metric.": "附加到每个 span/指标的额外资源属性。",
  "Extra resource attributes to attach to every span/metric. A static enduser.id set here always wins over the runtime identity.": "附加到每个 span/指标上的额外资源属性。此处设置的静态 enduser.id 始终优先于运行时身份。",
  "Extra seconds to wait for model output on a streaming response that is sending only keep-alive pings. Gateway provider only. Default 300.": "在流式响应仅发送保活 ping 时，额外等待模型输出的秒数。仅适用于网关提供方。默认 300。",
  "Extra string claims merged into the JWT, as a JSON object with string values.": "合并到 JWT 中的额外字符串声明，格式为带有字符串值的 JSON 对象。",
