  "Extra usage is off, so extra usage you buy now won’t cover usage past your plan limits until you turn it on. <link>Enable extra usage</link>": "额外用量已关闭，因此在您开启之前，现在购买的额外用量不会覆盖超出套餐限额的用量。<link>启用额外用量</link>",
